    println!();
    println!("  Note: Run `cargo xt test xt` or `cargo test -p xt` to test xt itself");
    print_hline!();
    println!();

    if failed > 0 {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

