use anyhow::Result;
use clap::Parser;
use std::process::ExitCode;

use xt::all::{build_all, print_run_summary, print_summary, print_test_summary, run_all, test_all};
use xt::binary::strip_binary;
use xt::build::build_crate;
use xt::cli::{Cli, Commands, SpecCommands};
use xt::compare::compare_specs;
use xt::find_paths::{find_crate_dir, find_tspecs, find_workspace_root};
use xt::run::run_binary;
use xt::testing::test_crate;
use xt::workspace::WorkspaceInfo;

fn main() -> ExitCode {
    match run() {
        Ok(code) => code,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::from(1)
        }
    }
}

fn run() -> Result<ExitCode> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Build {
            crate_name,
            tspec,
            release,
            strip,
            fail_fast,
        } => match crate_name {
            None => {
                // Build all crates
                let workspace = WorkspaceInfo::discover()?;
                let results = build_all(&workspace, tspec.as_deref(), release, strip, fail_fast);
                return Ok(print_summary(&results));
            }
            Some(name) => {
                let result = build_crate(&name, tspec.as_deref(), release)?;
                if strip {
                    strip_binary(&result.binary_path)?;
                }
            }
        },
        Commands::Run {
            crate_name,
            tspec,
            release,
            strip,
        } => match crate_name {
            None => {
                // Run all apps
                let workspace = WorkspaceInfo::discover()?;
                let results = run_all(&workspace, tspec.as_deref(), release, strip);
                return Ok(print_run_summary(&results));
            }
            Some(name) => {
                // Build, optionally strip, then run
                let result = build_crate(&name, tspec.as_deref(), release)?;
                if strip {
                    strip_binary(&result.binary_path)?;
                }
                let exit_code = run_binary(&result.binary_path)?;
                std::process::exit(exit_code);
            }
        },
        Commands::Test {
            crate_name,
            tspec,
            release,
            fail_fast,
        } => match crate_name {
            None => {
                // Test all crates
                let workspace = WorkspaceInfo::discover()?;
                let results = test_all(&workspace, tspec.as_deref(), release, fail_fast);
                return Ok(print_test_summary(&results));
            }
            Some(name) => {
                test_crate(&name, tspec.as_deref(), release)?;
            }
        },
        Commands::Compare {
            crate_name,
            tspec,
            release,
            strip,
        } => {
            let workspace = find_workspace_root()?;
            let crate_dir = find_crate_dir(&workspace, &crate_name)?;
            let spec_paths = find_tspecs(&crate_dir, &tspec)?;
            compare_specs(&crate_name, &spec_paths, release, strip)?;
        }
        Commands::Compat { crate_name, spec } => {
            match spec {
                Some(s) => println!("compat add: crate={crate_name} spec={s}"),
                None => println!("compat show: crate={crate_name}"),
            }
            // TODO: implement
        }
        Commands::Incompat { crate_name, spec } => {
            println!("incompat add: crate={crate_name} spec={spec}");
            // TODO: implement
        }
        Commands::Spec { command } => {
            match command {
                SpecCommands::List => {
                    println!("spec list");
                    // TODO: implement
                }
                SpecCommands::Show { name, crate_name } => {
                    println!("spec show: name={name} crate={crate_name:?}");
                    // TODO: implement
                }
                SpecCommands::Hash { name, crate_name } => {
                    println!("spec hash: name={name} crate={crate_name:?}");
                    // TODO: implement
                }
            }
        }
    }

    Ok(ExitCode::SUCCESS)
}

use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "xt")]
#[command(about = "Translation spec based build system")]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand)]
pub enum Commands {
    /// Build crate(s) with a translation spec
    Build {
        /// Crate to build (omit for all workspace members)
        crate_name: Option<String>,
        /// Translation spec to use (defaults to crate's tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Strip symbols from binary after build
        #[arg(short, long)]
        strip: bool,
        /// Stop on first failure (for all-crates mode)
        #[arg(short, long)]
        fail_fast: bool,
    },
    /// Build and run crate(s) with a translation spec
    Run {
        /// Crate to run (omit for all apps)
        crate_name: Option<String>,
        /// Translation spec to use (defaults to crate's tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Strip symbols from binary before running
        #[arg(short, long)]
        strip: bool,
    },
    /// Test crate(s) with a translation spec
    Test {
        /// Crate to test (omit for all workspace members)
        crate_name: Option<String>,
        /// Translation spec to use (defaults to crate's tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Stop on first failure
        #[arg(short, long)]
        fail_fast: bool,
    },
    /// Compare specs for a crate (size only)
    Compare {
        /// Crate to compare
        crate_name: String,
        /// Spec file(s) or glob pattern(s) (defaults to tspec*.xt.toml)
        #[arg(short = 't', long = "tspec", action = clap::ArgAction::Append)]
        tspec: Vec<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Strip symbols before comparing sizes
        #[arg(short, long)]
        strip: bool,
    },
    /// Manage crate compatibility with specs
    Compat {
        /// Crate name
        crate_name: String,
        /// Spec to add to compat list (omit to show current state)
        spec: Option<String>,
    },
    /// Mark a spec as incompatible with a crate
    Incompat {
        /// Crate name
        crate_name: String,
        /// Spec to add to incompat list
        spec: String,
    },
    /// Show or manage translation specs
    Spec {
        #[command(subcommand)]
        command: SpecCommands,
    },
}

#[derive(Subcommand)]
pub enum SpecCommands {
    /// List available global specs
    List,
    /// Show a spec (resolved with local mods if --crate specified)
    Show {
        /// Spec name
        name: String,
        /// Crate to apply local mods from
        #[arg(long = "crate")]
        crate_name: Option<String>,
    },
    /// Show the hash of a resolved spec
    Hash {
        /// Spec name
        name: String,
        /// Crate to apply local mods from
        #[arg(long = "crate")]
        crate_name: Option<String>,
    },
}

