     5→use crate::types::{CargoParam, Profile, Spec};
     6→
     7→/// Extract crate name from Cargo.toml
     8→pub fn get_crate_name(crate_dir: &Path) -> Result<String> {
     9→    let cargo_toml = crate_dir.join("Cargo.toml");
    10→    let content = std::fs::read_to_string(&cargo_toml)
    11→        .with_context(|| format!("failed to read {}", cargo_toml.display()))?;
    12→
    13→    // Simple parsing - look for name = "..." in [package] section
    14→    let mut in_package = false;
    15→    for line in content.lines() {
    16→        let line = line.trim();
    17→        if line == "[package]" {
    18→            in_package = true;
    19→            continue;
    20→        }
    21→        if line.starts_with('[') {
    22→            in_package = false;
    23→            continue;
    24→        }
    25→        if in_package
    26→            && line.starts_with("name")
    27→            && let Some(eq_pos) = line.find('=')
    28→        {
    29→            let value = line[eq_pos + 1..].trim();
    30→            let value = value.trim_matches('"').trim_matches('\'');
    31→            return Ok(value.to_string());
    32→        }
    33→    }
    34→    bail!("could not find package name in {}", cargo_toml.display());
    35→}
    36→
    37→/// Find the workspace root by looking for Cargo.toml with [workspace]
    38→pub fn find_workspace_root() -> Result<PathBuf> {
    39→    let mut dir = std::env::current_dir()?;
    40→    loop {
    41→        let cargo_toml = dir.join("Cargo.toml");
    42→        if cargo_toml.exists() {
    43→            let content = std::fs::read_to_string(&cargo_toml)?;
    44→            if content.contains("[workspace]") {
    45→                return Ok(dir);
    46→            }
    47→        }
    48→        if !dir.pop() {
    49→            bail!("could not find workspace root");
    50→        }
    51→    }
    52→}
    53→
    54→/// Find a crate's directory - tries as path first, then searches standard locations
    55→pub fn find_crate_dir(workspace: &Path, name: &str) -> Result<PathBuf> {
    56→    // Try as path first (relative or absolute)
    57→    let as_path = PathBuf::from(name);
    58→    if as_path.join("Cargo.toml").exists() {
    59→        return Ok(as_path.canonicalize().unwrap_or(as_path));
    60→    }
    61→
    62→    // Fallback: search libs/, apps/, tools/
    63→    for prefix in ["libs", "apps", "tools"] {
    64→        let path = workspace.join(prefix).join(name);
    65→        if path.join("Cargo.toml").exists() {
    66→            return Ok(path);
    67→        }
    68→    }
    69→
    70→    // Special case: nested test crates like libs/rlibc-x2/tests
    71→    for prefix in ["libs", "apps"] {
    72→        for entry in std::fs::read_dir(workspace.join(prefix)).into_iter().flatten() {
    73→            if let Ok(entry) = entry {
    74→                let nested = entry.path().join("tests");
    75→                if nested.join("Cargo.toml").exists() {
    76→                    // Check if this is the crate we're looking for
    77→                    if let Ok(pkg_name) = get_crate_name(&nested) {
    78→                        if pkg_name == name {
    79→                            return Ok(nested);
    80→                        }
    81→                    }
    82→                }
    83→            }
    84→        }
    85→    }
    86→
    87→    bail!("crate '{}' not found", name);
    88→}
    89→
    90→/// Find the tspec for a crate - tries as path first, then relative to crate_dir
    91→/// Returns None if no tspec exists (plain cargo build will be used)
    92→pub fn find_tspec(crate_dir: &Path, explicit: Option<&str>) -> Result<Option<PathBuf>> {
    93→    match explicit {
    94→        Some(name) => {
    95→            // Try as path first (relative to cwd or absolute)
    96→            let as_path = PathBuf::from(name);
    97→            if as_path.exists() {
    98→                return Ok(Some(as_path.canonicalize().unwrap_or(as_path)));
    99→            }
   100→
   101→            // Fallback: relative to crate directory
   102→            let in_crate = crate_dir.join(name);
   103→            if in_crate.exists() {
   104→                return Ok(Some(in_crate));
   105→            }
   106→
   107→            // Try with .xt.toml suffix if name has no extension
   108→            if !name.contains('.') {
   109→                let with_suffix = crate_dir.join(format!("{}.xt.toml", name));
   110→                if with_suffix.exists() {
   111→                    return Ok(Some(with_suffix));
   112→                }
   113→            }
   114→
   115→            bail!("tspec not found: {}", name);
   116→        }
   117→        None => {
   118→            let default = crate_dir.join("tspec.xt.toml");
   119→            if default.exists() {
   120→                Ok(Some(default))
   121→            } else {
   122→                Ok(None) // No tspec = plain cargo build
   123→            }
   124→        }
   125→    }
   126→}
   127→
   128→/// Find multiple tspecs by glob patterns
   129→/// If no patterns given, defaults to "tspec*.xt.toml"
   130→/// Returns sorted list of paths, errors if none found
   131→pub fn find_tspecs(crate_dir: &Path, patterns: &[String]) -> Result<Vec<PathBuf>> {
   132→    let patterns: Vec<&str> = if patterns.is_empty() {
   133→        vec!["tspec*.xt.toml"]
   134→    } else {
   135→        patterns.iter().map(|s| s.as_str()).collect()
   136→    };
   137→
   138→    let mut results = Vec::new();
   139→
   140→    for pattern in &patterns {
   141→        // Try as literal path first (relative to cwd or absolute)
   142→        let as_path = PathBuf::from(pattern);
   143→        if as_path.exists() && as_path.is_file() {
   144→            results.push(as_path.canonicalize().unwrap_or(as_path));
   145→            continue;
   146→        }
   147→
   148→        // Try as literal path relative to crate_dir
   149→        let in_crate = crate_dir.join(pattern);
   150→        if in_crate.exists() && in_crate.is_file() {
   151→            results.push(in_crate);
   152→            continue;
   153→        }
   154→
   155→        // Try as glob pattern in crate_dir
   156→        let glob_pattern = Pattern::new(pattern)
   157→            .with_context(|| format!("invalid glob pattern: {}", pattern))?;
   158→
   159→        let entries: Vec<_> = std::fs::read_dir(crate_dir)
   160→            .with_context(|| format!("cannot read directory: {}", crate_dir.display()))?
   161→            .filter_map(|e| e.ok())
   162→            .filter(|e| {
   163→                let name = e.file_name().to_string_lossy().to_string();
   164→                e.path().is_file() && glob_pattern.matches(&name)
   165→            })
   166→            .map(|e| e.path())
   167→            .collect();
   168→
   169→        results.extend(entries);
   170→    }
   171→
   172→    // Remove duplicates and sort
   173→    results.sort();
   174→    results.dedup();
   175→
   176→    if results.is_empty() {
   177→        let pattern_list = patterns.join(", ");
   178→        bail!(
   179→            "no tspec files found matching '{}' in {}",
   180→            pattern_list,
   181→            crate_dir.display()
   182→        );
   183→    }
   184→
   185→    Ok(results)
   186→}
