   188→/// Get binary path for a build with a spec
   189→pub fn get_binary_path(workspace: &Path, crate_name: &str, spec: &Spec, release: bool) -> PathBuf {
   190→    let is_release = release
   191→        || spec
   192→            .cargo
   193→            .iter()
   194→            .any(|p| matches!(p, CargoParam::Profile(Profile::Release)));
   195→
   196→    let target = spec.cargo.iter().find_map(|p| match p {
   197→        CargoParam::TargetTriple(t) => Some(t.clone()),
   198→        CargoParam::TargetJson(p) => p.file_stem().map(|s| s.to_string_lossy().to_string()),
   199→        _ => None,
   200→    });
   201→
   202→    let profile_dir = if is_release { "release" } else { "debug" };
   203→
   204→    match target {
   205→        Some(t) => workspace
   206→            .join("target")
   207→            .join(t)
   208→            .join(profile_dir)
   209→            .join(crate_name),
   210→        None => workspace.join("target").join(profile_dir).join(crate_name),
   211→    }
   212→}
   213→
   214→/// Get binary path for a simple build (no spec)
   215→pub fn get_binary_path_simple(workspace: &Path, crate_name: &str, release: bool) -> PathBuf {
   216→    let profile_dir = if release { "release" } else { "debug" };
   217→    workspace.join("target").join(profile_dir).join(crate_name)
   218→}
